    @Test void headingScopeRemovalRequiresExactReceiptNativeAbsenceAndCurrentSavedIdentity()throws Exception {
        Current before=range();Map<String,Object> scope=only(before,"body_range");BodyScopePatch choice=patch(scope);DocxEditResult result=before.apply(choice);List<Map<String,Object>> removed=DraftDocumentBindings.bodyEdited(before.bindings,result);Map<String,Object> receipt=DraftBodyCleanup.receipt("authored-parent",before.bytes,before.index,before.bindings,Collections.singletonList(choice),result);receipt.put("savedRevisionId","authored-immutable-revision");receipt.put("savedDocxSha256",result.getDocxSha256());List<Object> log=new ArrayList<>(result.getLedger());log.add(receipt);log=JsonUtils.readList(JsonUtils.write(log),Object.class);Current current=new Current(result.getDocxBytes(),removed,before.originalSourceSha);Set<String> wanted=new LinkedHashSet<>(strings(scope.get("memberBindingIds")));Map<String,Map<String,Object>> valid=headingEvidence(current,log,wanted);assertEquals(2,valid.size(),"Only the two original direct-body paragraphs are heading-profile endpoints; the table-cell member stays outside this authority");for(Map<String,Object> proof:valid.values()){assertEquals("explicit_body_scope_removed",proof.get("state"));assertEquals(true,proof.get("physicalRemoved"));assertEquals(true,proof.get("nativeBookmarkAbsent"));assertEquals(current.index.getSourceSha256(),proof.get("currentDocxSha256"));}
        for(String fault:Arrays.asList("savedSha","parentSha","operation","memberHash","targetHash","targetStatus","duplicateOperation","missingReceipt")){List<Object> changed=JsonUtils.readList(JsonUtils.write(log),Object.class);Map<String,Object> r=DraftBusinessRules.asMap(changed.get(changed.size()-1)),s=DraftBusinessRules.asMap(DraftBusinessRules.list(r.get("scopes")).get(0));if("savedSha".equals(fault))r.put("savedDocxSha256",String.join("",Collections.nCopies(64,"a")));if("parentSha".equals(fault))r.put("parentDocxSha256",String.join("",Collections.nCopies(64,"b")));if("operation".equals(fault))s.put("operation","clear_empty_numbering");if("memberHash".equals(fault))s.put("nodeSha256",String.join("",Collections.nCopies(64,"c")));if("targetHash".equals(fault))DraftBusinessRules.asMap(DraftBusinessRules.list(s.get("nativeTargets")).get(0)).put("sha256",String.join("",Collections.nCopies(64,"d")));if("targetStatus".equals(fault)){Map<String,Object> edit=DraftBusinessRules.asMap(DraftBusinessRules.list(s.get("appliedNativeEdits")).get(0));DraftBusinessRules.asMap(DraftBusinessRules.list(edit.get("targets")).get(0)).put("status","APPLIED");}if("duplicateOperation".equals(fault))changed.add(new LinkedHashMap<>(DraftBusinessRules.asMap(changed.get(0))));if("missingReceipt".equals(fault))changed.remove(r);assertTrue(headingEvidence(current,changed,wanted).isEmpty(),fault);}
        Paragraph retained=current.index.mainParagraph(1);DocxEditResult unrelated=EDITOR.apply(current.bytes,new SourceEditBatch(current.index.getSourceSha256(),Collections.singletonList(Edit.replaceSpan("ordinary-body-new-save",retained,0,retained.getText().length(),retained.getText(),retained.getText()+" changed"))));Current foreignCurrent=new Current(unrelated.getDocxBytes(),removed,before.originalSourceSha);assertTrue(headingEvidence(foreignCurrent,log,wanted).isEmpty(),"An unrecorded new current SHA cannot borrow the previous removal receipt");
    }

